-- AI generated by pi coding agent, v1.0
--
-- Remove duplicate measurement rows from `measurements`.
--
-- The CSV file was imported more than once, so every timestamp exists several
-- times (one row per import run). For a given `measured_at` only the row with
-- the highest `id` - i.e. the newest import - is kept.
--
-- Since commit 72d5d8f ("import_temperatures: unique index, duplicate check,
-- day-block import") the table carries `UNIQUE KEY uniq_measured_at
-- (measured_at)` and the importer skips existing timestamps, so duplicates can
-- no longer be produced. That key can only be created on a table that is
-- already free of duplicates - this script is the clean-up that made it
-- possible and is also the remedy if an older binary ever wrote duplicates
-- again.
--
-- Usage:
--   mysql -u <user> -p <db> < scripts/dedup_measurements.sql
--
-- The script is idempotent: running it twice deletes nothing the second time.
-- End of AI generated by pi coding agent, v1.0

-- Report the state before the clean-up.
SELECT 'before' AS phase,
       COUNT(*) AS rows_total,
       COUNT(DISTINCT measured_at) AS rows_distinct
FROM measurements;

-- Delete every row that is shadowed by a newer row with the same timestamp.
DELETE m_old
FROM measurements AS m_old
JOIN measurements AS m_new
  ON m_new.measured_at = m_old.measured_at
 AND m_new.id > m_old.id;

-- Report the state after the clean-up. Both counts must now be identical.
SELECT 'after' AS phase,
       COUNT(*) AS rows_total,
       COUNT(DISTINCT measured_at) AS rows_distinct
FROM measurements;
